// Realistic long steel I-beam

beam_length = 220;

height = 55;
flange_width = 42;
flange_thickness = 6;
web_thickness = 7;

inside_fillet = 4;
edge_radius = 0.8;

$fn = 48;

module i_beam_profile() {
    offset(r = edge_radius)
    offset(delta = -edge_radius)
    union() {
        translate([0, height/2 - flange_thickness/2])
            square([flange_width, flange_thickness], center=true);

        translate([0, -height/2 + flange_thickness/2])
            square([flange_width, flange_thickness], center=true);

        square([web_thickness, height], center=true);

        translate([ web_thickness/2,  height/2 - flange_thickness])
            circle(inside_fillet);
        translate([-web_thickness/2,  height/2 - flange_thickness])
            circle(inside_fillet);
        translate([ web_thickness/2, -height/2 + flange_thickness])
            circle(inside_fillet);
        translate([-web_thickness/2, -height/2 + flange_thickness])
            circle(inside_fillet);
    }
}

color([0.45, 0.46, 0.43])
rotate([90, 0, 0])
linear_extrude(height = beam_length)
    i_beam_profile();

