module tapered_flange_i_beam() {
  union() {
    linear_extrude(height = beam_length, center = true)
      polygon(points=[[-flange_width/2, beam_height/2-flange_thickness_outer], [flange_width/2, beam_height/2-flange_thickness_outer], [web_thickness/2, beam_height/2-flange_thickness_inner], [-web_thickness/2, beam_height/2-flange_thickness_inner]]);
    linear_extrude(height = beam_length, center = true)
      polygon(points=[[-flange_width/2, -beam_height/2+flange_thickness_outer], [flange_width/2, -beam_height/2+flange_thickness_outer], [web_thickness/2, -beam_height/2+flange_thickness_inner], [-web_thickness/2, -beam_height/2+flange_thickness_inner]]);
    cube([web_thickness, web_height, beam_length], center=true);
  }
}

