$fn = 48;

span = 180;
rise = 54;
depth = 38;
panel_count = 6;
truss_width = 8;
member_width = 6;
member_depth = 6;
gusset_radius = 9;
gusset_thickness = 2;
bolt_diameter = 2.5;
support_pad_length = 22;
support_pad_width = 18;

panel_length = span / panel_count;
roof_pitch_angle = atan(rise / (span/2));
rafter_length = sqrt((span/2)*(span/2) + rise*rise);
bridge_diagonal_length = sqrt(panel_length*panel_length + depth*depth);
gusset_plate_width = 2.5 * member_width;
minimum_bolt_edge_distance = 1.5 * bolt_diameter;

module member_between(p1, p2, w=member_width, d=member_depth) {
  dx = p2[0] - p1[0];
  dz = p2[1] - p1[1];
  L = sqrt(dx*dx + dz*dz);
  a = atan2(dz, dx);
  translate([(p1[0]+p2[0])/2, 0, (p1[1]+p2[1])/2])
    rotate([0, -a, 0])
      cube([L, d, w], center=true);
}

module gusset_at(p) {
  difference() {
    translate([p[0], 0, p[1]])
      cylinder(h=gusset_thickness, r=gusset_radius, center=true);
    translate([p[0], 0, p[1]])
      cylinder(h=gusset_thickness+1, d=bolt_diameter, center=true);
  }
}

module support_pad(x) {
  translate([x, 0, -member_width])
    difference() {
      cube([support_pad_length, support_pad_width, 3], center=true);
      for (y=[-support_pad_width/4, support_pad_width/4])
        translate([0, y, 0]) cylinder(h=4, d=bolt_diameter, center=true);
    }
}

module common_truss_feature_demo() {
  left = [-span/2, 0];
  right = [span/2, 0];
  apex = [0, rise];
  mid = [0, 0];
  union() {
    member_between(left, right);      // bottom chord
    member_between(left, apex);       // left top chord / rafter
    member_between(apex, right);      // right top chord / rafter
    member_between(mid, apex);        // vertical web / post
    member_between(left, [0, rise/2]); // diagonal web example
    member_between([0, rise/2], right);
    for (p=[left, right, apex, mid, [0, rise/2]]) gusset_at(p);
    support_pad(-span/2);
    support_pad(span/2);
  }
}

common_truss_feature_demo();

// King Post Roof Truss
// OpenSCAD
// Units: mm

$fn = 40;

span = 240;
rise = 80;

chord_d = 5;
web_d = 4;
joint_d = 8;

A = [-span/2, 0, 0];
B = [ span/2, 0, 0];
C = [0, 0, rise];
D = [0, 0, 0];

module rod(p1, p2, d=4) {
    v = p2 - p1;
    L = norm(v);
    translate(p1)
        rotate([0, acos(v[2] / L), atan2(v[1], v[0])])
            cylinder(d=d, h=L);
}

module node(p) {
    translate(p)
        sphere(d=joint_d);
}

module member(p1, p2, d=4) {
    rod(p1, p2, d);
    node(p1);
    node(p2);
}

module king_post_truss() {
    member(A, D, chord_d);
    member(D, B, chord_d);

    member(A, C, chord_d);
    member(C, B, chord_d);

    member(C, D, web_d);
}

king_post_truss();

