// Pratt Bridge / Roof Truss
// OpenSCAD
// Units: mm

$fn = 40;

span = 280;
height = 70;
bays = 8;

chord_d = 5;
web_d = 4;
joint_d = 8;

bay_w = span / bays;

module rod(p1, p2, d=4) {
    v = p2 - p1;
    L = norm(v);
    translate(p1)
        rotate([0, acos(v[2] / L), atan2(v[1], v[0])])
            cylinder(d=d, h=L);
}

module node(p) {
    translate(p)
        sphere(d=joint_d);
}

module member(p1, p2, d=4) {
    rod(p1, p2, d);
    node(p1);
    node(p2);
}

module pratt_truss() {
    for (i = [0:bays-1])
        member(
            [-span/2 + i * bay_w, 0, 0],
            [-span/2 + (i + 1) * bay_w, 0, 0],
            chord_d
        );

    for (i = [0:bays-1])
        member(
            [-span/2 + i * bay_w, 0, height],
            [-span/2 + (i + 1) * bay_w, 0, height],
            chord_d
        );

    for (i = [0:bays])
        member(
            [-span/2 + i * bay_w, 0, 0],
            [-span/2 + i * bay_w, 0, height],
            web_d
        );

    for (i = [0:floor(bays/2)-1])
        member(
            [-span/2 + i * bay_w, 0, 0],
            [-span/2 + (i + 1) * bay_w, 0, height],
            web_d
        );

    for (i = [floor(bays/2):bays-1])
        member(
            [-span/2 + i * bay_w, 0, height],
            [-span/2 + (i + 1) * bay_w, 0, 0],
            web_d
        );
}

