// K-Truss OpenSCAD model
// Units: mm

$fn = 32;

span = 160;
height = 55;

chord_d = 6;
web_d = 4;
joint_d = 8;

bays = 4;
bay_w = span / bays;

module bar_between(p1, p2, d=4) {
    v = p2 - p1;
    L = norm(v);
    translate(p1)
        rotate([0, acos(v[2] / L), atan2(v[1], v[0])])
            cylinder(d=d, h=L);
}

module joint(p) {
    translate(p)
        sphere(d=joint_d);
}

module member(p1, p2, d=4) {
    bar_between(p1, p2, d);
    joint(p1);
    joint(p2);
}

bottom = [
    [0, 0, 0],
    [bay_w, 0, 0],
    [2 * bay_w, 0, 0],
    [3 * bay_w, 0, 0],
    [4 * bay_w, 0, 0]
];

top = [
    [0, 0, height],
    [bay_w, 0, height],
    [2 * bay_w, 0, height],
    [3 * bay_w, 0, height],
    [4 * bay_w, 0, height]
];

module k_truss() {
    for (i = [0:bays-1]) {
        member(bottom[i], bottom[i+1], chord_d);
        member(top[i], top[i+1], chord_d);
    }

    member(bottom[0], top[0], chord_d);
    member(bottom[bays], top[bays], chord_d);

    for (i = [0:bays-1]) {
        mid = [(i + 0.5) * bay_w, 0, height / 2];
        member(bottom[i], mid, web_d);
        member(top[i], mid, web_d);
        member(bottom[i+1], mid, web_d);
        member(top[i+1], mid, web_d);
    }

    for (i = [1:bays-1]) {
        member(bottom[i], top[i], web_d);
    }
}

translate([-span/2, 0, -height/2])
    k_truss();
